wb_route('POST', '/auth/login', function ($c) { if (!wb_rate('login:' . $c['ipHash'], 20, 60)) { throw new WbHttpError(429, '로그인 시도가 너무 많습니다. 1분 뒤 다시 시도해 주세요.'); } $r = wb_login(wb_b($c, 'loginId'), wb_b($c, 'password'), $c); wb_daily_tasks($c); $u = wb_get('SELECT * FROM users WHERE id = ?', array((int)$r['user']['id'])); try { $c2 = $c; $c2['user'] = $u; wb_log($c2, null, 'auth.login', 'user', (int)$u['id'], '로그인 ' . $u['login_id']); } catch (Exception $e) {} $sites = array(); foreach (wb_sites($u) as $s) { $sites[] = wb_site_out($s, array('user' => $u, 'host' => $c['host'], 'config' => $c['config'], 'baseUrl' => $c['baseUrl'])); } return array_merge(array('sites' => $sites, 'platform' => 'php'), $r); }, array('open' => true));
wb_route('POST', '/auth/logout', function ($c) { if (!empty($c['user'])) { try { wb_log($c, null, 'auth.logout', 'user', (int)$c['user']['id'], '로그아웃 ' . $c['user']['login_id']); } catch (Exception $e) {} } wb_logout($c['token']); return array(); }, array('open' => true));
