wb_route('PUT', '/auth/password', function ($c) { $u = wb_get('SELECT * FROM users WHERE id = ?', array((int)$c['user']['id'])); if (!wb_verify_password(wb_str(wb_b($c, 'current')), $u['password_hash'])) { throw new WbHttpError(422, '현재 비밀번호가 올바르지 않습니다.'); } $err = wb_valid_password(wb_b($c, 'next')); if ($err) { throw new WbHttpError(422, $err); } if ((string)wb_b($c, 'next') === (string)wb_b($c, 'current')) { throw new WbHttpError(422, '현재 비밀번호와 다른 새 비밀번호를 입력해 주세요.'); } wb_update('users', array('password_hash' => wb_hash_password(wb_b($c, 'next')), 'must_change_password' => 0, 'updated_at' => wb_now()), 'id = ?', array((int)$u['id'])); wb_log($c, null, 'user.password', 'user', (int)$u['id'], '비밀번호 변경'); return array(); });
