wb_route('GET', '/notifications', function ($c) { $sites = array(); foreach (wb_sites($c['user']) as $s) { if (wb_can($c['user'], (int)$s['id'], 'submissions')) { $sites[] = (int)$s['id']; } } if (!count($sites)) { return array('unseen' => 0, 'items' => array()); } $gsFailed = function_exists('wb_gs_failed_count') ? wb_gs_failed_count($sites) : 0; if (function_exists('wb_gs_has_due') && wb_gs_has_due()) { $cc = $c; wb_after_response(function () use ($cc) { wb_gs_retry_due($cc, 2, 15); }); } $since = !empty($c['user']['notif_seen_at']) ? $c['user']['notif_seen_at'] : '2000-01-01'; $items = array_map(function ($r) { return wb_ints($r, array('id', 'site_id')); }, wb_all('SELECT s.id, s.name, s.site_id, s.created_at, st.name AS site_name FROM form_submissions s JOIN sites st ON st.id = s.site_id WHERE s.site_id IN (' . wb_in($sites) . ') AND s.deleted_at IS NULL AND s.created_at > ? ORDER BY s.id DESC LIMIT 10', array_merge($sites, array($since)))); return array('unseen' => wb_int(wb_val('SELECT COUNT(*) FROM form_submissions WHERE site_id IN (' . wb_in($sites) . ') AND deleted_at IS NULL AND created_at > ?', array_merge($sites, array($since)))), 'items' => $items, 'gs_failed' => $gsFailed); });
