wb_route('GET', '/dashboard', function ($c) {
  $sites = wb_sites($c['user']); $t = wb_today(); $week = wb_today(wb_days(-6)); $list = array(); $ids = array(); $subIds = array();
  foreach ($sites as $s) { $o = wb_site_out($s, $c); $o['week_visitors'] = wb_int(wb_val("SELECT COUNT(DISTINCT session_hash) FROM analytics_events WHERE site_id = ? AND event = 'pageview' AND created_at >= ?", array((int)$s['id'], $week . ' 00:00:00'))); $o['month_subs'] = wb_int(wb_val('SELECT COUNT(*) FROM form_submissions WHERE site_id = ? AND deleted_at IS NULL AND created_at >= ?', array((int)$s['id'], substr($t, 0, 7) . '-01 00:00:00'))); $o['alerts'] = wb_site_alerts($s); $list[] = $o; $ids[] = (int)$s['id']; if (wb_can($c['user'], (int)$s['id'], 'submissions') || wb_can($c['user'], (int)$s['id'], 'submissions.view')) { $subIds[] = (int)$s['id']; } }
  $recent = array(); if (count($subIds)) { foreach (wb_all('SELECT s.id, s.site_id, st.name AS site_name, s.name, s.phone, s.visit_date, s.visit_time, s.status, s.created_at FROM form_submissions s JOIN sites st ON st.id = s.site_id WHERE s.site_id IN (' . wb_in($subIds) . ') AND s.deleted_at IS NULL ORDER BY s.id DESC LIMIT 10', $subIds) as $r) { $r = wb_ints($r, array('id', 'site_id')); $r['phone'] = wb_mask_phone($r['phone'], wb_can($c['user'], $r['site_id'], 'submissions')); $st = wb_statuses(); $r['status_label'] = isset($st[$r['status']]) ? $st[$r['status']] : $r['status']; $recent[] = $r; } }
  $logs = wb_is_super($c['user']) ? wb_all('SELECT l.*, u.name AS user_name, st.name AS site_name FROM activity_logs l LEFT JOIN users u ON u.id = l.user_id LEFT JOIN sites st ON st.id = l.site_id ORDER BY l.id DESC LIMIT 12') : (count($ids) ? wb_all('SELECT l.*, u.name AS user_name, st.name AS site_name FROM activity_logs l LEFT JOIN users u ON u.id = l.user_id LEFT JOIN sites st ON st.id = l.site_id WHERE l.site_id IN (' . wb_in($ids) . ') ORDER BY l.id DESC LIMIT 12', $ids) : array());
