  $todaySubs = count($subIds) ? wb_int(wb_val('SELECT COUNT(*) FROM form_submissions WHERE site_id IN (' . wb_in($subIds) . ') AND deleted_at IS NULL AND created_at >= ?', array_merge($subIds, array($t . ' 00:00:00')))) : 0;
  $newSubs = count($subIds) ? wb_int(wb_val("SELECT COUNT(*) FROM form_submissions WHERE site_id IN (" . wb_in($subIds) . ") AND deleted_at IS NULL AND status = 'new'", $subIds)) : 0;
  $smsFailed = count($subIds) ? wb_int(wb_val("SELECT COUNT(*) FROM sms_logs WHERE site_id IN (" . wb_in($subIds) . ") AND status = 'failed' AND created_at >= ?", array_merge($subIds, array(wb_now(time() - 7 * 86400))))) : 0;
  $lastPub = count($ids) ? wb_get("SELECT p.version_no, p.created_at, st.name AS site_name FROM publish_snapshots p JOIN sites st ON st.id = p.site_id WHERE p.site_id IN (" . wb_in($ids) . ") AND (p.status IS NULL OR p.status IN ('published', 'local-only')) ORDER BY p.id DESC LIMIT 1", $ids) : null;
  $smsState = null; if (wb_is_super($c['user']) && function_exists('wb_sms_status')) { try { $ss = wb_sms_status($c); $smsState = array('state' => $ss['state'], 'provider' => $ss['providerName'], 'serverIp' => $ss['serverIp']); } catch (Exception $e) { $smsState = null; } }
  $lastPubOut = $lastPub ? array('version' => (int)$lastPub['version_no'], 'at' => $lastPub['created_at'], 'site' => $lastPub['site_name']) : null;
  $lastRs = count($ids) ? wb_get("SELECT created_at, summary FROM activity_logs WHERE action = 'site.publish_restore' AND site_id IN (" . wb_in($ids) . ") ORDER BY id DESC LIMIT 1", $ids) : null;
