function wb_create_site_from_input($c, $b, $userId) {
  $key = wb_keyify(!empty($b['key']) ? $b['key'] : wb_slugify(isset($b['name']) ? $b['name'] : '')); if ($key === '' || strlen($key) < 2) { throw new WbHttpError(422, '사이트 식별값(영문 · 숫자)을 입력해 주세요.'); }
