  $siteOpts = array('site' => array('name' => wb_str($b['name'], 80))); if (!empty($b['tel'])) { $siteOpts['site']['tel'] = wb_str($b['tel'], 30); } if ($publicUrl !== '') { $siteOpts['site']['url'] = $publicUrl; }
