function wb_validate_settings($group, $data) {
  $bad = function ($label, $why) { throw new WbHttpError(422, $label . ' : ' . $why, array('field' => $label)); };
  $tel = function ($v, $l) use ($bad) { if ($v === null || $v === '') { return; } $v = trim((string)$v); if (!preg_match('/^[0-9+\-() .]{4,24}$/', $v) || strlen(preg_replace('/[^0-9]/', '', $v)) < 7) { $bad($l, '전화번호 형식이 올바르지 않습니다. (예 1600-0000 · 02-123-4567)'); } };
  $mail = function ($v, $l) use ($bad) { if ($v === null || $v === '') { return; } if (!preg_match('/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/', trim((string)$v))) { $bad($l, '이메일 형식이 올바르지 않습니다.'); } };
  $url = function ($v, $l) use ($bad) { if ($v === null || $v === '') { return; } if (!preg_match('/^https?:\/\/[^\s]+$/i', trim((string)$v))) { $bad($l, '주소는 http:// 또는 https:// 로 시작해야 합니다.'); } };
  $color = function ($v, $l) use ($bad) { if ($v === null || $v === '') { return; } if (!preg_match('/^(#([0-9a-f]{3}|[0-9a-f]{6}|[0-9a-f]{8})|rgba?\(\s*\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3}\s*(,\s*(0|1|0?\.\d+)\s*)?\))$/i', trim((string)$v))) { $bad($l, '색상은 #002F47 · rgb(0,47,71) · rgba(0,47,71,.5) 형식으로 입력해 주세요.'); } };
  if ($group === 'site' && is_array(wb_prop($data, 'site'))) { $s = $data['site']; $tel(isset($s['tel']) ? $s['tel'] : null, '대표번호'); $tel(isset($s['smsTel']) ? $s['smsTel'] : null, '문자 문의 번호'); $tel(isset($s['mobile']) ? $s['mobile'] : null, '휴대전화번호'); $mail(isset($s['email']) ? $s['email'] : null, '대표 이메일'); $mail(isset($s['reserveEmail']) ? $s['reserveEmail'] : null, '방문예약 담당자 이메일'); $url(isset($s['kakaoUrl']) ? $s['kakaoUrl'] : null, '카카오톡 상담 링크'); $url(isset($s['naverMap']) ? $s['naverMap'] : null, '네이버지도 링크'); $url(isset($s['kakaoMap']) ? $s['kakaoMap'] : null, '카카오지도 링크'); }
