function wb_put_settings_route($c, $s, $group) { if (in_array($group, array('gsheets', 'notify'), true)) { throw new WbHttpError(403, '이 설정은 사이트 설정 › 외부 연동 화면에서 바꿀 수 있습니다.'); } $dataObj = wb_bo($c, 'data'); if (!is_object($dataObj)) { throw new WbHttpError(422, '설정 형식이 올바르지 않습니다.'); } wb_validate_settings($group, wb_arr($dataObj)); $before = wb_get_setting((int)$s['id'], $group); wb_put_setting((int)$s['id'], $group, $dataObj, (int)$c['user']['id']); if ($group === 'site' && isset($dataObj->site) && is_object($dataObj->site)) { $d = array(); $ss = $dataObj->site; if (isset($ss->tel)) { $d['tel'] = wb_str($ss->tel, 30); } if (!empty($ss->name)) { $d['name'] = wb_str($ss->name, 80); } if (isset($ss->fieldName)) { $d['field_name'] = wb_str($ss->fieldName, 80); } if (!empty($ss->url) && preg_match('#^https?://[^\s/]+#i', (string)$ss->url)) { $d['public_url'] = preg_replace('#/(index\.html)?$#', '', wb_str($ss->url, 200)); } if (count($d)) { $d['updated_at'] = wb_now(); wb_update('sites', $d, 'id = ?', array((int)$s['id'])); } } wb_log($c, (int)$s['id'], 'settings.update', 'settings', null, $group . ' 설정 변경', $before, $dataObj); return array('group' => $group); }
