function wb_compile_menu($siteId) { $menu = wb_get("SELECT id FROM menus WHERE site_id = ? AND `key` = 'main'", array((int)$siteId)); if (!$menu) { return array(); } $items = wb_all('SELECT * FROM menu_items WHERE menu_id = ? ORDER BY sort, id', array((int)$menu['id'])); $out = array(); foreach ($items as $g) { if (!empty($g['parent_id'])) { continue; } $children = array(); foreach ($items as $ch) { if ((int)$ch['parent_id'] !== (int)$g['id']) { continue; } $it = array('enabled' => (int)$ch['enabled'] === 1, 'page' => (string)$ch['page_key'], 'label' => $ch['label']); if ($ch['link_type'] === 'url' && !empty($ch['url'])) { $it['url'] = $ch['url']; $it['target'] = $ch['target'] ? $ch['target'] : '_self'; } $children[] = $it; } $out[] = array('enabled' => (int)$g['enabled'] === 1, 'id' => $g['page_key'] ? $g['page_key'] : $g['label'], 'label' => $g['label'], 'latin' => (string)$g['latin'], 'items' => $children); } return $out; }
