wb_route('PUT', '/sites/:id/menus/main', function ($c, $p) { $s = wb_site_of($c, $p['id'], 'manage'); $menu = wb_b($c, 'menu'); if (!is_array($menu)) { throw new WbHttpError(422, '메뉴 형식이 올바르지 않습니다.'); } wb_tx(function () use ($s, $menu) { $m = wb_get("SELECT id FROM menus WHERE site_id = ? AND `key` = 'main'", array((int)$s['id'])); $mid = $m ? (int)$m['id'] : wb_insert('menus', array('site_id' => (int)$s['id'], 'key' => 'main', 'name' => '메인 메뉴', 'updated_at' => wb_now())); wb_del('menu_items', 'menu_id = ?', array($mid)); $sort = 0; foreach ($menu as $g) { $g = wb_arr($g); $pid = wb_insert('menu_items', array('menu_id' => $mid, 'parent_id' => null, 'label' => wb_str(isset($g['label']) ? $g['label'] : '', 60), 'latin' => wb_str(isset($g['latin']) ? $g['latin'] : '', 60), 'link_type' => 'group', 'page_key' => wb_str(isset($g['id']) ? $g['id'] : '', 60), 'url' => '', 'target' => '_self', 'sort' => $sort++, 'enabled' => (isset($g['enabled']) && $g['enabled'] === false) ? 0 : 1)); $cs = 0; foreach ((array)(isset($g['items']) ? $g['items'] : array()) as $it) { $it = wb_arr($it); wb_insert('menu_items', array('menu_id' => $mid, 'parent_id' => $pid, 'label' => wb_str(isset($it['label']) ? $it['label'] : '', 60), 'latin' => '', 'link_type' => !empty($it['url']) ? 'url' : 'page', 'page_key' => wb_str(isset($it['page']) ? $it['page'] : '', 60), 'url' => wb_str(isset($it['url']) ? $it['url'] : '', 500), 'target' => wb_str(!empty($it['target']) ? $it['target'] : '_self', 20), 'sort' => $cs++, 'enabled' => (isset($it['enabled']) && $it['enabled'] === false) ? 0 : 1)); } } wb_update('menus', array('updated_at' => wb_now()), 'id = ?', array($mid)); }); wb_log($c, (int)$s['id'], 'menu.update', 'menu', null, '메뉴 수정'); return array(); });

