/* 내용이 비어 있는 페이지 수 (메인이 비면 홈 화면 · 공통 내용이 비어 게시가 위험) */
/* 게시본 버전의 구성 개수 (게시 파일은 이 값으로 만들어집니다 — 여기가 0 이면 공개 홈페이지가 빈 화면이 됩니다) */
function wb_published_sections_count($row) {
  if (!$row || empty($row['published_version_id'])) { return -1; }
  $v = wb_get('SELECT content_json FROM page_versions WHERE id = ?', array((int)$row['published_version_id']));
  if (!$v) { return -1; }
  $j = wb_json_safe($v['content_json'], null);
  if (!is_object($j)) { return -1; }
  return isset($j->sections) && is_array($j->sections) ? count($j->sections) : 0;
}
function wb_pages_empty_info($siteId) {
  $empty = array(); $mainEmpty = false; $mainPubEmpty = false;
  foreach (wb_all('SELECT * FROM pages WHERE site_id = ? AND deleted_at IS NULL', array((int)$siteId)) as $r) {
    if (function_exists('wb_import_page_empty') && wb_import_page_empty($r)) { $empty[] = (string)$r['key']; if ((string)$r['type'] === 'main') { $mainEmpty = true; } }
    if ((string)$r['type'] === 'main' && (string)$r['status'] === 'published' && wb_published_sections_count($r) === 0) { $mainPubEmpty = true; }   /* 초안은 멀쩡한데 게시본만 비어 있는 경우 */
  }
  return array('emptyPages' => $empty, 'mainEmpty' => $mainEmpty, 'mainPublishedEmpty' => $mainPubEmpty, 'needsRepairMain' => ($mainEmpty || $mainPubEmpty));
}
