wb_route('GET', '/pages/trash', function ($c) { $s = wb_current_site($c); return array('pages' => array_map(function ($r) { return wb_ints($r, array('id')); }, wb_all('SELECT id, `key`, title, deleted_at FROM pages WHERE site_id = ? AND deleted_at IS NOT NULL ORDER BY deleted_at DESC LIMIT 50', array((int)$s['id'])))); });
wb_route('POST', '/pages/reorder', function ($c) { $s = wb_current_site($c, 'edit'); $i = 0; foreach ((array)wb_b($c, 'ids', array()) as $id) { wb_update('pages', array('sort' => $i++), 'id = ? AND site_id = ?', array(wb_int($id), (int)$s['id'])); } return array(); });
wb_route('PATCH', '/pages/:id/meta', function ($c, $p) { $pg = wb_page_of($c, $p['id'], 'edit'); $b = $c['body']; $d = array(); if (wb_has($b, 'title')) { $d['title'] = wb_str($b['title'], 150); } if (wb_has($b, 'category')) { $d['category'] = wb_str($b['category'], 60); } if (wb_has($b, 'layout_type')) { $d['layout_type'] = wb_str($b['layout_type'], 40); } if (wb_has($b, 'visible')) { if ($pg['type'] === 'main') { throw new WbHttpError(422, '메인 페이지는 항상 공개됩니다.'); } $vis = wb_bool($b['visible']); $d['status'] = $vis ? ($pg['published_version_id'] ? 'published' : 'draft') : 'stopped'; if (!$vis) { $d['publish_at'] = null; } } $d['updated_at'] = wb_now(); wb_update('pages', $d, 'id = ?', array((int)$pg['id'])); if (isset($d['status'])) { wb_log($c, (int)$pg['site_id'], $d['status'] === 'stopped' ? 'page.hide' : 'page.show', 'page', (int)$pg['id'], ($d['status'] === 'stopped' ? '페이지 숨김 ' : '페이지 공개 ') . $pg['title']); } if (isset($d['title']) && $d['title'] !== $pg['title']) { wb_log($c, (int)$pg['site_id'], 'page.rename', 'page', (int)$pg['id'], '페이지 이름 변경 ' . $pg['title'] . ' → ' . $d['title']); } return array('status' => isset($d['status']) ? $d['status'] : $pg['status']); });
wb_route('DELETE', '/pages/:id', function ($c, $p) { $pg = wb_page_of($c, $p['id'], 'edit'); if ($pg['type'] === 'main') { throw new WbHttpError(422, '메인 페이지는 삭제할 수 없습니다.'); } wb_update('pages', array('deleted_at' => wb_now(), 'updated_at' => wb_now()), 'id = ?', array((int)$pg['id'])); wb_log($c, (int)$pg['site_id'], 'page.delete', 'page', (int)$pg['id'], '페이지 휴지통 ' . $pg['title']); return array(); });
wb_route('POST', '/pages/:id/restore', function ($c, $p) { $pg = wb_page_of($c, $p['id'], 'edit', true); wb_update('pages', array('deleted_at' => null, 'updated_at' => wb_now()), 'id = ?', array((int)$pg['id'])); wb_log($c, (int)$pg['site_id'], 'page.restore_trash', 'page', (int)$pg['id'], '휴지통 복구 ' . $pg['title']); return array(); });
wb_route('GET', '/blocks', function ($c) { $s = wb_current_site($c); return array('blocks' => array_map(function ($b) { return array('id' => (int)$b['id'], 'key' => $b['key'], 'name' => $b['name'], 'section' => wb_json_safe($b['fields_json'], new stdClass())); }, wb_all("SELECT id, `key`, name, fields_json FROM section_types WHERE site_id = ? AND scope = 'saved' ORDER BY sort, id", array((int)$s['id'])))); });
wb_route('POST', '/blocks', function ($c) { $s = wb_current_site($c, 'edit'); $sec = wb_bo($c, 'section'); if (!is_object($sec) || empty($sec->type)) { throw new WbHttpError(422, '저장할 섹션 정보가 없습니다.'); } $id = wb_insert('section_types', array('site_id' => (int)$s['id'], 'key' => 'saved-' . substr(wb_hex(4), 0, 6), 'name' => wb_str(wb_b($c, 'name'), 120) ?: '저장한 블록', 'scope' => 'saved', 'fields_json' => wb_enc($sec), 'sort' => wb_int(wb_val('SELECT COUNT(*) FROM section_types WHERE site_id = ?', array((int)$s['id']))))); return array('id' => $id); });
wb_route('DELETE', '/blocks/:id', function ($c, $p) { $s = wb_current_site($c, 'edit'); wb_del('section_types', "id = ? AND site_id = ? AND scope = 'saved'", array((int)$p['id'], (int)$s['id'])); return array(); });

/* ================= 폼 ================= */
function wb_form_of($c, $id, $ability = 'view') { $f = wb_get('SELECT * FROM forms WHERE id = ?', array((int)$id)); if (!$f) { throw new WbHttpError(404, '폼을 찾을 수 없습니다.'); } wb_site_of($c, (int)$f['site_id'], $ability); return $f; }
wb_route('GET', '/sites/:id/forms', function ($c, $p) { $s = wb_site_of($c, $p['id']); return array('forms' => array_map(function ($f) { return array('id' => (int)$f['id'], 'key' => $f['key'], 'name' => $f['name'], 'version' => (int)$f['version'], 'status' => $f['status'], 'updated_at' => $f['updated_at'], 'has_draft' => !empty($f['draft_json'])); }, wb_all('SELECT id, `key`, name, version, status, updated_at, draft_json FROM forms WHERE site_id = ?', array((int)$s['id'])))); });
wb_route('GET', '/forms/:id', function ($c, $p) { $f = wb_form_of($c, $p['id']); $draft = wb_form_draft((int)$f['id']); return array('schema' => $draft ? $draft : wb_form_schema((int)$f['id']), 'published' => wb_form_schema((int)$f['id']), 'hasDraft' => (bool)$draft); });
wb_route('PUT', '/forms/:id', function ($c, $p) { $f = wb_form_of($c, $p['id'], 'edit'); $base = wb_form_draft((int)$f['id']); if (!$base) { $base = wb_form_schema((int)$f['id']); } $settingsObj = wb_bo($c, 'settings'); $settings = is_object($settingsObj) ? $settingsObj : $base['settings']; if (is_array($settings)) { $settings = (object)$settings; } if (!isset($settings->visitTimes) || !is_array($settings->visitTimes) || !count($settings->visitTimes)) { $settings->visitTimes = wb_visit_times(); } $fields = is_array(wb_b($c, 'fields')) ? wb_b($c, 'fields') : $base['fields']; $seen = array(); foreach ($fields as $x) { $x = wb_arr($x); $k = preg_replace('/[^a-zA-Z0-9_]/', '', wb_str(isset($x['name']) ? $x['name'] : '')); if ($k === '') { throw new WbHttpError(422, '필드 이름(영문)이 비어 있는 항목이 있습니다 : ' . wb_str(isset($x['label']) ? $x['label'] : '')); } if (isset($seen[$k])) { throw new WbHttpError(422, '필드 이름(영문)이 겹칩니다 : ' . $k); } $seen[$k] = true; } $pub = wb_form_schema((int)$f['id']); $same = wb_enc(array('s' => wb_arr($settings), 'f' => wb_normalize_fields($fields))) === wb_enc(array('s' => wb_arr($pub['settings']), 'f' => wb_normalize_fields($pub['fields']))); if ($same) { wb_discard_form_draft((int)$f['id']); } else { wb_save_form_draft((int)$f['id'], $settings, $fields, (int)$c['user']['id']); } if (wb_b($c, 'name')) { wb_update('forms', array('name' => wb_str(wb_b($c, 'name'), 120)), 'id = ?', array((int)$f['id'])); } if (!wb_bool(wb_b($c, 'quiet'))) { wb_log($c, (int)$f['site_id'], 'form.update', 'form', (int)$f['id'], '폼 초안 저장 ' . $f['name']); } $draft = wb_form_draft((int)$f['id']); return array('schema' => $draft ? $draft : wb_form_schema((int)$f['id']), 'hasDraft' => (bool)$draft); });
wb_route('DELETE', '/forms/:id/draft', function ($c, $p) { $f = wb_form_of($c, $p['id'], 'edit'); wb_discard_form_draft((int)$f['id']); wb_log($c, (int)$f['site_id'], 'form.discard', 'form', (int)$f['id'], '폼 초안 버림 ' . $f['name']); return array('schema' => wb_form_schema((int)$f['id']), 'hasDraft' => false); });
